CREATE OR REPLACE FUNCTION public.olt_indicators(p_row jsonb, p_today date DEFAULT ((now() AT TIME ZONE 'America/Lima'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
 planned date:=(p_row->>'fecha')::date; sap date:=(p_row->>'fecha_salida_sap')::date;
 cargo date:=(p_row->>'fec_cargo')::date; due date; delta integer; state text; delay text;
 months text[]:=array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
begin
 due:=public.olt_workdays(coalesce(sap,planned),public.olt_due_days(p_row->>'linea',p_row->>'departamento',p_row->>'despacho'));
 if due is not null then
  delta:=coalesce(cargo,p_today)-due;
  state:=case when cargo is not null then case when cargo<=due then 'Cumple' else 'No Cumple' end
   when due=p_today then 'Vencen Hoy' when due>p_today then 'Por Vencer' else 'Cargo Pendiente' end;
  delay:=case when cargo is not null and delta<=0 then '-' when delta>0 then delta||' días de retraso'
   when delta=0 then 'Vence hoy 0 días' else 'Vence en '||abs(delta)||' días' end;
 end if;
 return jsonb_build_object('fec_vencto',due,'indicador',case when due is null then '' when coalesce(cargo,p_today)<=due then 'En Fecha' else 'Fuera de Fecha' end,
 'estado_cargo',coalesce(state,''),'retraso',coalesce(delay,''),'mes_olt',coalesce(months[extract(month from planned)::integer],''),
 'mes_sap',coalesce(months[extract(month from sap)::integer],''),'dias_plan_salida',case when planned is null or sap is null then '' else abs(planned-sap)||case when abs(planned-sap)=1 then ' día' else ' días' end end,
 'rules_version','2026.1');
end $function$

CREATE OR REPLACE FUNCTION public.olt_insertar_lote(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
 v_uid uuid := (select auth.uid()); v_inserted integer; v_latest timestamptz;
begin
 if v_uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>500 then
  raise exception 'Expected an array of at most 500 records' using errcode='22023';
 end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where jsonb_typeof(x) is distinct from 'object') then
  raise exception 'Each record must be an object' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(v_uid::text,142019));
 with incoming as materialized (
  select r.*,item->>'archivo' as source_file,item->>'archivo_hash' as source_hash,item->>'pestana' as source_sheet,
   ord,public.olt_business_key(r.fecha,r.area,r.entrega,r.factura,r.gr,r.turno,r.cita,r.razon,r.distrito,r.provincia,r.departamento,r.linea,r.bultos,r.volumen,r.peso,r.despacho,r.transporte,r.mercaderia,r.observacion) as business_key
  from jsonb_array_elements(p_rows) with ordinality as x(item,ord)
  cross join lateral jsonb_populate_record(null::public.recepcion_olt,jsonb_build_object('fecha',item->'fecha','area',item->'area','entrega',item->'entrega','factura',item->'factura','gr',item->'gr','turno',item->'turno','cita',item->'cita','razon',item->'razon','distrito',item->'distrito','provincia',item->'provincia','departamento',item->'departamento','linea',item->'linea','bultos',item->'bultos','volumen',item->'volumen','peso',item->'peso','despacho',item->'despacho','transporte',item->'transporte','mercaderia',item->'mercaderia','observacion',item->'observacion')) r
 ), unique_rows as materialized (
  select distinct on (business_key) * from incoming order by business_key,ord
 ), existing as materialized (
  select public.olt_business_key(r.fecha,r.area,r.entrega,r.factura,r.gr,r.turno,r.cita,r.razon,r.distrito,r.provincia,r.departamento,r.linea,r.bultos,r.volumen,r.peso,r.despacho,r.transporte,r.mercaderia,r.observacion) as business_key
  from public.recepcion_olt r where r.usuario_id=v_uid
 ), inserted as (
  insert into public.recepcion_olt(fecha,area,entrega,factura,gr,turno,cita,razon,distrito,provincia,departamento,linea,bultos,volumen,peso,despacho,transporte,mercaderia,observacion,usuario_id,usuario,archivo,archivo_hash,pestana)
  select r.fecha,r.area,r.entrega,r.factura,r.gr,r.turno,r.cita,r.razon,r.distrito,r.provincia,r.departamento,r.linea,r.bultos,r.volumen,r.peso,r.despacho,r.transporte,r.mercaderia,r.observacion,v_uid,coalesce(auth.jwt()->>'email',auth.jwt()->>'phone',v_uid::text),r.source_file,r.source_hash,r.source_sheet
  from unique_rows r where not exists(select 1 from existing e where e.business_key=r.business_key)
  order by r.ord returning created_at
 ) select count(*)::int,max(created_at) into v_inserted,v_latest from inserted;
 return jsonb_build_object('insertados',v_inserted,'duplicados',jsonb_array_length(p_rows)-v_inserted,'ultima_fecha',v_latest);
end $function$

CREATE OR REPLACE FUNCTION olt_private.sap_publish(p_load bigint, p_ack boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); c olt_control.sap_cargas; old bigint; summary jsonb;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,817));
 select * into c from olt_control.sap_cargas where id=p_load and usuario_id=u for update;
 if c.id is null or c.estado<>'validando' then raise exception 'Carga no publicable'; end if;
 select carga_activa_id into old from olt_control.sap_estado_usuario where usuario_id=u;
 if old is distinct from c.base_carga_id then raise exception 'Otra carga se publicó mientras validabas. Vuelve a seleccionar el archivo.'; end if;
 summary:=public.olt_sap_summary(p_load);
 if (summary->>'valid')::integer<>c.total_filas-c.filas_invalidas or (summary->>'unique')::integer<1 then raise exception 'Carga incompleta'; end if;
 if (summary->>'previous_unique')::integer>0 and (summary->>'unique')::numeric < (summary->>'previous_unique')::numeric*0.7 and not p_ack then raise exception 'Confirma la caída superior al 30%% antes de publicar'; end if;
 insert into olt_control.sap_snapshot(usuario_id,carga_id,referencia,inacttrans,hraitr,dt,et,placa,estado_viaje,estado_entrega,fec_reg,hor_reg,usua_ctrl_re)
 select u,p_load,referencia,inacttrans,hraitr,dt,et,placa,estado_viaje,estado_entrega,fec_reg,hor_reg,usua_ctrl_re
 from (select distinct on(referencia) * from olt_control.sap_staging where carga_id=p_load order by referencia,inacttrans desc nulls last,hraitr desc nulls last,fila_origen) s;
 update olt_control.sap_cargas set estado='publicada',publicada_at=now(),procesada_at=now(),referencias_unicas=(summary->>'unique')::integer,
 referencias_nuevas=(summary->>'new')::integer,referencias_actualizadas=(summary->>'modified')::integer,mensaje='Publicación transaccional completa',alertas=alertas||jsonb_build_array(summary) where id=p_load and usuario_id=u;
 insert into olt_control.sap_estado_usuario(usuario_id,carga_activa_id) values(u,p_load) on conflict(usuario_id) do update set carga_activa_id=excluded.carga_activa_id,updated_at=now();
 return summary;
end $function$

CREATE OR REPLACE FUNCTION olt_private.sap_start(p_file text, p_hash text, p_valid integer, p_invalid integer, p_alerts jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); cid bigint; old bigint;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 if p_hash is null or p_hash !~ '^[0-9a-f]{64}$' or p_file is null or length(p_file)>255 or p_valid<1 or p_valid>250000 or p_invalid<0 or p_invalid::numeric/(p_valid+p_invalid)>0.1 then raise exception 'Metadatos de carga inválidos'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,817));
 if exists(select 1 from olt_control.sap_cargas where usuario_id=u and archivo_hash=p_hash and estado='publicada') then raise exception 'Este archivo ya fue publicado'; end if;
 select carga_activa_id into old from olt_control.sap_estado_usuario where usuario_id=u;
 insert into olt_control.sap_cargas(usuario_id,archivo,archivo_hash,total_filas,filas_invalidas,estado,schema_version,base_carga_id,alertas)
 values(u,p_file,p_hash,p_valid+p_invalid,p_invalid,'validando',3,old,coalesce(p_alerts,'[]'::jsonb)) returning id into cid;
 return cid;
end $function$

CREATE OR REPLACE FUNCTION olt_private.save_cell(p_id bigint, p_key text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); g olt_control.gestion_olt; data jsonb;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,817));
 if not exists(select 1 from public.recepcion_olt where id=p_id and usuario_id=u) then raise exception 'Registro no disponible' using errcode='42501'; end if;
 if exists(select 1 from olt_control.cierre_mensual where olt_id=p_id) then raise exception 'Mes cerrado: no se puede editar'; end if;
 if p_key is null or p_key<>all(array['nro_cargo','fec_cargo','codigo_transporte','placa_prog','dt_prog','transporte_prog','responsable','motivo']) or length(p_value)>2000 then raise exception 'Columna o valor inválido'; end if;
 select * into g from olt_control.gestion_olt where olt_id=p_id;
 data:=coalesce(to_jsonb(g),'{}'::jsonb)||jsonb_build_object(p_key,nullif(btrim(p_value),''));
 select * into g from jsonb_populate_record(null::olt_control.gestion_olt,data);
 insert into olt_control.gestion_olt(olt_id,nro_cargo,fec_cargo,codigo_transporte,placa_prog,dt_prog,transporte_prog,responsable,motivo,updated_by)
 values(p_id,g.nro_cargo,g.fec_cargo,g.codigo_transporte,g.placa_prog,g.dt_prog,g.transporte_prog,g.responsable,g.motivo,u)
 on conflict(olt_id) do update set nro_cargo=excluded.nro_cargo,fec_cargo=excluded.fec_cargo,codigo_transporte=excluded.codigo_transporte,placa_prog=excluded.placa_prog,dt_prog=excluded.dt_prog,transporte_prog=excluded.transporte_prog,responsable=excluded.responsable,motivo=excluded.motivo,updated_by=u,updated_at=now();
 select row_data into data from public.olt_control_rows where id=p_id and usuario_id=u;
 return data;
end $function$

CREATE OR REPLACE FUNCTION olt_private.close_month(p_period date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); n integer;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 if p_period is null or p_period<>date_trunc('month',p_period)::date or p_period>=date_trunc('month',now() at time zone 'America/Lima')::date then raise exception 'Solo se pueden cerrar meses completos anteriores'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,817));
 if exists(select 1 from olt_control.cierre_mensual c join public.recepcion_olt r on r.id=c.olt_id where c.periodo=p_period and r.usuario_id=u) then raise exception 'Este mes ya está cerrado'; end if;
 insert into olt_control.cierre_mensual(periodo,olt_id,entrega,snapshot,cerrado_por)
 select p_period,id,entrega,row_data || public.olt_indicators(row_data) || jsonb_build_object('periodo',p_period,'cerrado_at',now(),'cerrado_por',u),u
 from public.olt_control_live where usuario_id=u and fecha>=p_period and fecha<(p_period+interval '1 month')::date;
 get diagnostics n=row_count;
 if n=0 then raise exception 'El mes no tiene filas para cerrar'; end if;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.olt_workdays(p_start date, p_days integer)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare d date:=p_start; n integer:=greatest(p_days,0);
begin
 if p_days>30 then raise exception 'Plazo fuera de reglas OLT'; end if;
 if d is null then return null; end if;
 while n>0 loop
  d:=d+1;
  if extract(isodow from d)<6 and not exists(select 1 from public.calendario_feriados f where f.fecha=d and f.activo) then n:=n-1; end if;
 end loop;
 return d;
end $function$

CREATE OR REPLACE FUNCTION olt_private.sap_failure(p_file text, p_hash text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid();
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 if p_hash is null or p_hash !~ '^[0-9a-f]{64}$' then raise exception 'Hash inválido'; end if;
 insert into olt_control.sap_cargas(usuario_id,archivo,archivo_hash,estado,procesada_at,mensaje,schema_version)
 values(u,left(p_file,255),p_hash,'rechazada',now(),left(p_error,500),3);
end $function$

CREATE OR REPLACE FUNCTION olt_private.sap_append(p_load bigint, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); c olt_control.sap_cargas; n integer;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 select * into c from olt_control.sap_cargas where id=p_load and usuario_id=u for update;
 if c.id is null or c.estado<>'validando' then raise exception 'Carga no disponible'; end if;
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>400 or jsonb_array_length(p_rows)<1 then raise exception 'Lote inválido'; end if;
 if exists(select 1 from jsonb_populate_recordset(null::olt_control.sap_staging,p_rows) r where
 r.referencia is null or length(btrim(r.referencia))=0 or length(r.referencia)>100 or r.fila_origen is null or r.fila_origen<1
 or (r.raw_data is not null and (jsonb_typeof(r.raw_data)<>'object' or length(r.raw_data::text)>8192
 or (r.raw_data ? 'report_version' and r.raw_data->>'report_version'<>'1')
 or (r.raw_data ? 'excluido_reporte' and jsonb_typeof(r.raw_data->'excluido_reporte')<>'boolean')
 or (nullif(r.raw_data->>'fecha_alternativa','') is not null and (r.raw_data->>'fecha_alternativa')!~ '^\d{4}-\d{2}-\d{2}$')))) then raise exception 'Fila o metadatos SAP inválidos'; end if;
 -- Cast alternatives before insertion, rejecting impossible dates atomically.
 perform (r.raw_data->>'fecha_alternativa')::date from jsonb_populate_recordset(null::olt_control.sap_staging,p_rows) r where nullif(r.raw_data->>'fecha_alternativa','') is not null;
 if exists(select 1 from jsonb_populate_recordset(null::olt_control.sap_staging,p_rows) group by fila_origen having count(*)>1) then raise exception 'Fila física repetida en el lote'; end if;
 if exists(select 1 from jsonb_populate_recordset(null::olt_control.sap_staging,p_rows) r join olt_control.sap_staging s on s.carga_id=p_load and s.fila_origen=r.fila_origen
 where row(s.referencia,s.inacttrans,s.hraitr,s.dt,s.et,s.placa,s.estado_viaje,s.estado_entrega,s.fec_reg,s.hor_reg,s.usua_ctrl_re,s.raw_data)
 is distinct from row(btrim(r.referencia),r.inacttrans,r.hraitr,r.dt,r.et,r.placa,r.estado_viaje,r.estado_entrega,r.fec_reg,r.hor_reg,r.usua_ctrl_re,coalesce(r.raw_data,'{}'::jsonb))) then raise exception 'El lote repetido contiene datos diferentes'; end if;
 insert into olt_control.sap_staging(carga_id,fila_origen,referencia,inacttrans,hraitr,dt,et,placa,fecha_salida_sap,estado_viaje,estado_entrega,fec_reg,hor_reg,usua_ctrl_re,raw_data)
 select p_load,r.fila_origen,btrim(r.referencia),r.inacttrans,r.hraitr,r.dt,r.et,r.placa,r.inacttrans,r.estado_viaje,r.estado_entrega,r.fec_reg,r.hor_reg,r.usua_ctrl_re,coalesce(r.raw_data,'{}'::jsonb)
 from jsonb_populate_recordset(null::olt_control.sap_staging,p_rows) r on conflict(carga_id,fila_origen) do nothing;
 select count(*) into n from olt_control.sap_staging where carga_id=p_load;
 if n>c.total_filas-c.filas_invalidas then raise exception 'Más filas que las declaradas'; end if;
 return jsonb_array_length(p_rows);
end $function$

CREATE OR REPLACE FUNCTION olt_private.insertar_lote_durable(p_job uuid, p_batch integer, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); h text; receipt public.olt_upload_batches; r jsonb;
begin
 if u is null then raise exception 'Se requiere sesión' using errcode='42501'; end if;
 if p_job is null or p_batch is null or p_batch<0 or p_batch>10000 or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>500 or jsonb_array_length(p_rows)<1 then raise exception 'Lote inválido'; end if;
 h:=encode(sha256(convert_to(p_rows::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended(u::text||p_job::text,812021));
 select * into receipt from public.olt_upload_batches where usuario_id=u and job_id=p_job and batch_no=p_batch;
 if receipt.job_id is not null then
  if receipt.payload_hash<>h then raise exception 'El lote ya confirmado tiene contenido diferente'; end if;
  return receipt.result;
 end if;
 r:=public.olt_insertar_lote(p_rows);
 insert into public.olt_upload_batches(usuario_id,job_id,batch_no,payload_hash,result) values(u,p_job,p_batch,h,r);
 return r;
end $function$

CREATE OR REPLACE FUNCTION olt_private.save_cell_checked(p_id bigint, p_key text, p_value text, p_expected timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); v timestamptz; result jsonb;
begin
 if u is null or not exists(select 1 from public.recepcion_olt where id=p_id and usuario_id=u) then raise exception 'Registro no disponible' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,817));
 select updated_at into v from olt_control.gestion_olt where olt_id=p_id;
 if v is distinct from p_expected then raise exception 'La fila cambió en otra sesión. Actualiza antes de editar.' using errcode='40001'; end if;
 result:=olt_private.save_cell(p_id,p_key,p_value);
 select updated_at into v from olt_control.gestion_olt where olt_id=p_id;
 return result||jsonb_build_object('gestion_version',v);
end $function$
